WHO = {'column': [('dukklelefya', 0), ('eindfools', 0), ('maeefelor', 0), ('mulllgepy', 0), ('aprilfools', 0), ('norlllllllut', 0), ('eindfellben', 238641), ('psillgepy', 238641)], 'bridge': [('eindfellben', 0), ('psiloceyeben', 238583), ('mulwei', 238641), ('alphafoldmicro', 0), ('dukklewei', 238796), ('norlllelefya', 0), ('aprilllledum', 0), ('norlllelefya', 239319)], 'tree': [('eindfellyvi', 238920), ('dukklkize', 238984), ('dukkllgepy', 0), ('qufollellyvi', 239197), ('dukkllledum', 0), ('solkeellyvi', 0), ('eindfellyvi', 240527), ('aprilanor', 0)], 'tower': [('dukklewei', 0), ('renslelledum', 239133), ('einsof', 241905), ('loorfelor', 243801), ('renslellllut', 0), ('dukkllgepy', 245329), ('aprilllledum', 0), ('zeasflgepy', 246660)], 'manor': [('qufollellyvi', 241905), ('eindfellyvi', 247290), ('eindfellyvi', 0), ('muut', 247725), ('muut', 0), ('eindfools', 250081), ('qufollellyvi', 251551)], 'castle': [('psillben', 0), ('rensllben', 244288), ('dukkllgepy', 244288), ('ashllelefya', 250081)], 'temple': [('qullllut', 0), ('norlllllllut', 245084), ('zeasflgepy', 247168), ('eindfellllut', 250081)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW21(OracleReleaseRuntimeW20):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
